validated as (
  select seed.*
  from seed
  where jsonb_array_length(seed.accepted) > 0
    and seed.prompt <> seed.display
)
insert into public.question_bank(sport_id,category_key,question_type,format_key,prompt_i18n,clue_i18n,answer_rule,answer_display_i18n,difficulty_b,difficulty_percentile,editorial_difficulty_percentile,difficulty_confidence,quality_score,ambiguity_score,verification_status,source_id,source_url,source_title,content_hash,reviewed_at,active)
select s.id,validated.category_key,'typed_single','classic_trivia',jsonb_build_object('en',validated.prompt),jsonb_build_object('en',validated.clue),jsonb_build_object('accepted',validated.accepted),jsonb_build_object('en',validated.display),case when validated.percentile<.25 then -1.3 when validated.percentile<.5 then -.3 when validated.percentile<.75 then .7 else 1.5 end,validated.percentile,validated.percentile,0,1,0,'verified',editorial.id,validated.source_url,validated.source_title,encode(extensions.digest(validated.prompt,'sha256'),'hex'),now(),true
from validated join public.sports s on s.slug=validated.sport_slug cross join editorial on conflict do nothing;

